<script setup lang="ts">
import { copyText } from '../clipboard'
import { reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import PageShell from '../PageShell.vue'
import {usePage} from '../page'
import {api} from '../api'
import {loadSite} from '../site'
type Settings={site_name:string;panel_url:string;agent_host:string;agent_port:number;installer_url:string;release_base_url:string;agent_version:string;install_token_minutes:number}
const form=reactive<Settings>({site_name:'Nekopass',panel_url:'',agent_host:'',agent_port:9443,installer_url:'https://github.com/hajidishu/nekopass/releases/latest/download/install-agent.sh',release_base_url:'https://github.com/hajidishu/nekopass/releases/download',agent_version:'latest',install_token_minutes:30})
const updateInfo=ref<{current_version:string;latest:{version:string;url:string};update_available:boolean}|null>(null),checkingUpdate=ref(false)
async function checkUpdate(){checkingUpdate.value=true;try{updateInfo.value=await api('admin/updates')}catch(e){ElMessage.error((e as Error).message)}finally{checkingUpdate.value=false}}
const hasKey=ref(false),customKey=ref(''),shownKey=ref(''),keyDialog=ref(false)
const {me,loading,error,busy,run}=usePage(async()=>{const data=await api<{settings:Settings;api_key_configured:boolean}>('admin/settings');Object.assign(form,data.settings);hasKey.value=data.api_key_configured},{admin:true})
function currentAddress(){form.panel_url=location.origin;form.agent_host=location.hostname.replace(/^\[|\]$/g,'')}
async function save(){await run(async()=>{await api('admin/settings','PUT',form);await loadSite();ElMessage.success('系统设置已保存')})}
async function key(){try{if(hasKey.value)await ElMessageBox.confirm('生成或设置新密钥会使旧管理 API 密钥失效。','更新管理密钥',{confirmButtonText:'更新',cancelButtonText:'取消'});await run(async()=>{const data=await api<{key:string}>('admin/settings/api-key','POST',{key:customKey.value});shownKey.value=data.key;customKey.value='';hasKey.value=true;keyDialog.value=true})}catch{/* cancelled */}}
async function revoke(){try{await ElMessageBox.confirm('撤销后，现有管理 API 密钥将不能调用后台接口。','撤销管理密钥',{confirmButtonText:'撤销',cancelButtonText:'取消'});await run(async()=>{await api('admin/settings/api-key','DELETE',{});hasKey.value=false;ElMessage.success('管理 API 密钥已撤销')})}catch{/* cancelled */}}
async function copyKey(){try{await copyText(shownKey.value);ElMessage.success('密钥已复制')}catch{ElMessage.warning('复制失败，请手动选择复制')}}
</script>
<template><PageShell :me="me" :loading="loading" :error="error" active="settings" admin><section class="surface"><div class="section-header"><strong>系统设置</strong><el-button type="primary" :loading="busy" @click="save">保存设置</el-button></div><div class="section-body settings-form"><el-form label-position="top" @submit.prevent="save"><div class="form-section-title">软件更新</div><el-button :loading="checkingUpdate" @click="checkUpdate">检查更新</el-button><p v-if="updateInfo" class="field-tip">当前主控 {{updateInfo.current_version}} · 最新版本 <a :href="updateInfo.latest.url" target="_blank" rel="noopener">{{updateInfo.latest.version}}</a> · {{updateInfo.update_available?'有可用更新':'已是最新版本'}}。主控更新：<code>nekopassctl panel update</code>；节点更新在节点管理操作。</p><div class="form-section-title">站点与连接地址</div><el-form-item label="站点名称"><el-input v-model="form.site_name" maxlength="64" /></el-form-item><el-form-item label="面板对外地址"><el-input v-model="form.panel_url" placeholder="https://panel.example.com" /><el-button class="settings-inline-action" @click="currentAddress">填入当前面板地址</el-button></el-form-item><div class="form-grid"><el-form-item label="Agent 主控域名 / IP"><el-input v-model="form.agent_host" placeholder="panel.example.com" /></el-form-item><el-form-item label="Agent 控制端口"><el-input-number v-model="form.agent_port" :min="1" :max="65535" /></el-form-item></div><p class="field-tip">填写节点能访问的外部地址。面板访问端口与 Agent 控制端口可以不同；此处不会修改主控服务的实际监听端口，也不会自动改变已有节点的连接地址。</p><div class="form-section-title">节点一键安装</div><p class="field-tip">一键安装始终可用。默认从 GitHub Releases 下载，也可修改为自己的 HTTPS 下载源。</p><el-form-item label="安装脚本地址"><el-input v-model="form.installer_url" placeholder="https://github.com/hajidishu/nekopass/releases/latest/download/install-agent.sh" /></el-form-item><el-form-item label="Agent 版本下载根地址"><el-input v-model="form.release_base_url" placeholder="https://github.com/hajidishu/nekopass/releases/download" /></el-form-item><div class="form-grid"><el-form-item label="Agent 版本"><el-input v-model="form.agent_version" placeholder="latest" /></el-form-item></div><el-button type="primary" :loading="busy" native-type="submit">保存设置</el-button></el-form><div class="form-section-title api-key-section">管理 API 密钥</div><p class="subtle">{{hasKey?'已配置管理 API 密钥。原值不会再次显示。':'尚未配置管理 API 密钥。'}}此密钥用于自动化管理接口，不是节点密钥，也不会包含在节点安装命令中。</p><el-input v-model="customKey" type="password" show-password autocomplete="new-password" placeholder="可填写 32–256 字符自定义密钥，留空自动生成" /><div class="admin-actions settings-key-actions"><el-button :loading="busy" @click="key">{{hasKey?'更新管理 API 密钥':'生成管理 API 密钥'}}</el-button><el-button v-if="hasKey" type="danger" plain :loading="busy" @click="revoke">撤销密钥</el-button></div></div></section><el-dialog v-model="keyDialog" title="保存管理 API 密钥" width="600px" @closed="shownKey=''" ><p>只显示这一次，请保存到自己的密钥管理工具中。</p><el-input :model-value="shownKey" type="textarea" :rows="3" readonly /><template #footer><el-button type="primary" @click="copyKey">复制密钥</el-button></template></el-dialog></PageShell></template>
